"""Experimental joint economic planner with exact daily resource routing.

The established opening is retained through day 5. Thereafter decisions are
state based; no recorded future command stream is used. Not yet promoted.
"""
from collections import Counter, deque
from pathlib import Path
import sys
import math
import time
import copy

ROOT=Path(__file__).resolve().parent
from . import gpt6_rules as rules
from .gpt6_policy import Planner, PRODUCTS, ANIMALS, sd, moves, dist, fibcost, needs
from .gpt6_math_routes import solve_routes
from .project_model import CropDP, Project, animal_project
from .market_model import MarketModel, cohort_supply, empty_flows, add_project

JOINT_REPORT={'days':[], 'errors':[]}

def without_future(project, day):
    row=project.first(day)
    return Project(project.value,(row,))

class JointPlanner(Planner):
    def __init__(self):
        super().__init__(solve_routes,dict(setup_hours=2,crew_dynamic=False,crew_cap=15,route_ms=40))
        self.future=None

    def begin_day(self,obs):
        began=time.perf_counter()
        day=int(obs['step'])//24;self.day=day
        self.jobs=[];self.queues=[];self.plan_ready=False;self.buy_land=False
        self.want_seeds=Counter();self.want_animals=Counter();self.want_resources=Counter()
        farm=obs['farms'][obs['player']];private=obs['private']
        book=MarketModel(obs)
        own=cohort_supply(farm,day,1.0,1.0)
        if self.future is not None:
            # Keep only the old plan's not-yet-realized flow. Actual observations
            # and a fresh optimization replace yesterday's commitments below.
            for k in own:
                for d in range(day+1,30): own[k][d]=self.future[k][d]
        labor=[4.0]*30
        project_map={}
        prices=None
        for iteration in range(3):
            prices=book.marginal(own)
            # Locations share the same economy; location-dependent travel is
            # accounted for separately when choosing irreversible investment.
            dp=CropDP(prices,labor,[2.0]*30,start=day)
            generated=empty_flows();work=[0.0]*30
            project_map={}
            animal_cache={}
            for y,row in enumerate(farm['tiles']):
                for x,tile in enumerate(row):
                    if tile=='LOCKED': continue
                    pos=(x,y)
                    if isinstance(tile,dict) and 'animal' in tile:
                        key=tuple(sorted(tile.items()))
                        if key not in animal_cache:
                            animal_cache[key]=animal_project(tile['animal'],tile['placed_day'],day,tile,prices,labor,[2.0]*30)
                        proj=animal_cache[key]
                    elif isinstance(tile,dict) and tile.get('kind')=='PLANT':
                        proj=dp.existing(tile,day)
                    else:
                        proj=dp.free[day]
                    project_map[pos]=proj
                    add_project(generated,proj)
                    for d,ops,_,_ in proj.days:
                        if ops: work[d]+=len(ops)+1.4+sd(pos)/8
            for k in own:
                for d in range(day,30): own[k][d]=.5*own[k][d]+.5*generated[k][d]
            # Marginal labor cost rises sharply with the Fibonacci wage curve.
            # A small dual step avoids moving the whole field to a new crop at
            # once merely because that crop's old forecast omitted its supply.
            for d in range(day,30):
                hands=max(1,min(16,math.ceil(work[d]/21)-1))
                shadow=max(1.0,(fibcost(hands+1)-fibcost(hands))/21)
                labor[d]=.5*labor[d]+.5*shadow
        self.future=generated
        # Cash constraint protects mandatory maintenance before new projects.
        budget=farm['money']+sum(n*obs['market']['prices'].get(k,0)*.85 for k,n in private['shed'].items() if k in PRODUCTS)
        herd=sum(isinstance(t,dict) and 'animal' in t for row in farm['tiles'] for t in row)
        budget-=fibcost(12)+herd*obs['market']['prices']['WHEAT']+200
        quads=len(farm['unlocked_quadrants']);self.target_quads=quads
        # Land is valued through the same full-horizon crop opportunity. The
        # current day's far-field jobs still need a real route before execution.
        free_value=dp.free[day].value
        if quads<4 and day<=21:
            cost=(1000,2000,4000)[quads-1]
            if budget>cost+1800 and 25*free_value>cost*1.5:
                self.buy_land=True;self.target_quads+=1;budget-=cost
                q=rules.LAND_ORDER[quads-1]
                for y in range(10):
                    for x in range(10):
                        if rules._quadrant_of(x,y,10)==q:
                            project_map[(x,y)]=dp.free[day]
        # New animals compete with crop land rent and all dated feed/care costs.
        # Sequential revaluation inserts each accepted animal into supply first.
        animal_options={}
        new_counts=Counter()
        available=sorted(project_map,key=lambda pos:(sd(pos),pos))
        for pos in available:
            x,y=pos;tile=farm['tiles'][y][x];proj=project_map[pos]
            row=proj.first(day);ops=[list(o) for o in row[1]]
            existing=isinstance(tile,dict) and (tile.get('kind')=='PLANT' or 'animal' in tile)
            if not existing and sd(pos)<=4 and day<=18:
                if not animal_options:
                    for animal in rules.ANIMALS:
                        at=rules._new_animal(animal,day)
                        p=animal_project(animal,day,day,at,prices,labor,[2+sd(pos)/3]*30)
                        value=p.value-rules.ANIMALS[animal]['cost']-2*labor[day]-free_value
                        animal_options[animal]=(value,p)
                animal,(value,p)=max(animal_options.items(),key=lambda kv:kv[1][0])
                cost=rules.ANIMALS[animal]['cost']
                if value>0 and budget>cost+100:
                    ops=([['DIG']] if tile not in (None,'LOCKED') else [])
                    ops += [['BUILD_'+rules.ANIMALS[animal]['structure']],['PLACE',animal]]
                    ops += [list(o) for o in p.first(day)[1]]
                    budget-=cost;self.want_animals[animal]+=1;new_counts[animal]+=1
                    # Recompute marginal revenues from the updated whole book.
                    add_project(own,p)
                    prices=book.marginal(own)
                    animal_options={}
                    project_map[pos]=p;proj=p;row=p.first(day)
            if not ops: continue
            if not existing and pos not in () and tile not in (None,'LOCKED') and ops[0][0]!='DIG':
                ops.insert(0,['DIG'])
            # Commit a new seed only if it can be paid. Preserve existing crop
            # service/harvest when a same-day replacement cannot be financed.
            accepted=[]
            for op in ops:
                if op[0]=='PLANT':
                    c=op[1];cost=rules.CROPS[c]['seed']
                    held=private['seeds'].get(c,0)-self.want_seeds[c]
                    if held<=0 and budget<cost: break
                    self.want_seeds[c]+=1
                    if held<=0: budget-=cost
                accepted.append(op)
            if not accepted: continue
            production=sum(n*prices.get(k,[0]*30)[day] for k,n in row[2])
            future=max(0,proj.value)
            emergency=existing and (tile.get('consecutive_unwatered',0)>=1 or tile.get('consecutive_unfed',0)>=1)
            priority=production+min(1000,future)*.1+10000*emergency
            self.add_job(pos,accepted,priority,existing)
        for job in self.jobs: self.want_resources.update(needs(job['ops']))
        self.herd_count=herd+sum(new_counts.values())
        # No bulk restocking for an animal the DP deliberately retired.
        self.choose_crew(obs)
        JOINT_REPORT['days'].append(dict(day=day,projects=len(project_map),jobs=len(self.jobs),
            crew=self.crew,new_animals=dict(new_counts),seeds=dict(self.want_seeds),
            resources=dict(self.want_resources),land=self.buy_land,seconds=time.perf_counter()-began))

    def choose_crew(self,obs):
        # Select by actual packed job coverage and wage, including the return
        # trip on day29. Uncovered live crops/animals are heavily penalized.
        resources=Counter(obs['private']['shed'])
        for k,n in self.want_resources.items(): resources[k]=max(resources[k],n)
        positions=[(4,4)]
        for _ in range(15): positions.append(min(((4,4),(5,4),(4,5),(5,5)),key=positions.count))
        lower=max(1,math.ceil((sum(len(j['ops']) for j in self.jobs)+len(self.jobs))/22)-2)
        best=None
        for hands in range(max(1,min(lower,15)),16):
            workers=[dict(pos=p,hour=2,inv={}) for p in positions[:hands+1]]
            result=self.solve(self.jobs,workers,dict(resources),last_hour=22 if self.day==29 else 23,
                track_collect=True,evaluation_budget=3000,return_to_shed=self.day==29,end_service=1)
            lost=sum(self.jobs[j]['priority']+(5000 if self.jobs[j]['mandatory'] else 0) for j in result['unassigned'])
            score=fibcost(hands)+lost
            if best is None or score<best[0]: best=score,hands
            if not result['unassigned']: break
        self.crew=best[1]


